const LESSON = [
 {id:"s1",part:"Kick-off",slides:"9–12",title:"Cosa si aspetta Joël, e la regola sull'AI",
  brief:"Le aspettative sono: partecipazione attiva, pensiero critico, collaborazione, ricerca autonoma, apprendimento pratico, feedback costruttivo, presenza costante. Sull'AI la regola è una sola: deve sostenere il tuo pensiero, non sostituirlo.",
  hook:"Per il progetto vale doppio: un fatto su IBM inventato o non verificato dall'AI non conta come evidenza.",
  ex:"Sì: farti spiegare Williamson, generare domande, proporre lenti possibili, strutturare idee, migliorare il linguaggio. No: generare la diagnosi finale, inventare fatti su IBM, sostituire la ricerca delle fonti, delegare l'interpretazione della teoria.",
  q:"Puoi chiedere all'AI di riassumere un report di IBM che non hai letto e citare il riassunto come fonte?",
  a:"No. L'AI può riassumere solo materiale che hai già verificato, e il riassunto non è evidenza: la fonte resta il report."},
 {id:"s2",part:"Kick-off",slides:"13",title:"La mappa del corso: 7 capitoli, 3 fasi",
  brief:"Foundations & Context (Cap. 1–3: credenze, economia, teorie). Organizational Basics (Cap. 4–5: scopo, stakeholder, struttura, processi). Systems & Adaptation (Cap. 6–7: complessità, persone, cultura, apprendimento).",
  hook:"Il corso va dal perché esistono le organizzazioni, al come funzionano, a come sopravvivono in un mondo che cambia.",
  ex:"Per IBM: i Cap. 1–3 ti danno le lenti, i Cap. 4–5 cosa osservare (scopo, ruoli, decision rights), i Cap. 6–7 le tensioni più interessanti da discutere.",
  q:"In quale capitolo rientrano \"decision rights\" e \"handovers\"?",
  a:"Nel Cap. 5, Work, Structures & Processes: tasks, roles and decision rights; processes, coordination and handovers."},
 {id:"s3",part:"Kick-off",slides:"15–18",title:"La missione: diagnosticare, con informazioni incomplete",
  brief:"Siete nel dipartimento di Organizational Design e il Head of Strategy vi chiede una diagnosi indipendente: come funziona oggi l'organizzazione, perché potrebbe essere organizzata così, dove potrebbe migliorare. I passi sono quattro: Prepare (desk research), Investigate (Q&A), Interpret (pattern e tensioni), Diagnose & Recommend.",
  hook:"L'evidenza ha quattro etichette: FACT (fonte pubblica), FINDING (dalla Q&A), INTERPRETATION (conclusione tramite teoria), ASSUMPTION (ciò che credi, con informazioni incomplete).",
  ex:"Esempio costruito, da non usare così com'è. FACT: IBM ha acquisito Red Hat nel 2019. FINDING: \"Red Hat mantiene processi propri\" (ipotetica risposta alla Q&A). INTERPRETATION: con la lente sociotecnica, integrare poco evita di rompere un sistema che funziona. ASSUMPTION: probabilmente esistono tensioni culturali tra i due mondi.",
  q:"\"IBM è lenta perché è grande\": che tipo di affermazione è?",
  a:"Un'ASSUMPTION. Per diventare diagnosi servono fatti (es. tempi decisionali), un finding dalla Q&A e una lente che spieghi il meccanismo (es. decisionale o contingency)."},
 {id:"s4",part:"Kick-off",slides:"20–23",title:"Cosa deve contenere il progetto",
  brief:"Requisiti minimi: Purpose & Context; Structure & Processes; almeno tre lenti teoriche; People, Culture & Learning; Fit & Trade-offs; una o due raccomandazioni realistiche con benefici e rischi. Presentazione di 15 minuti con una storia coerente, depth over breadth.",
  hook:"Il messaggio chiave: il vostro compito è diagnosticare, non descrivere. Una buona analisi non finge di sapere tutto, rende visibile l'incertezza.",
  ex:"Domanda sprecata alla Q&A: \"Quanti dipendenti ha IBM?\" (si trova online). Domanda utile: \"Quando un progetto coinvolge sia cloud sia consulting, chi ha l'ultima parola?\"",
  q:"Perché aprire la presentazione con la storia di IBM dal 1911 è una cattiva idea?",
  a:"È descrizione. La storia serve solo se spiega un pattern di oggi; in 15 minuti conta una diagnosi coerente."},
 {id:"s5",part:"Kick-off",slides:"26–27",title:"Come funziona l'esame",
  brief:"Valuta concetti chiave, prospettive teoriche, la capacità di riconoscere concetti nelle situazioni, implicazioni e trade-off. Formato: multiple choice, single choice, scenari, short case.",
  hook:"Il consiglio della slide: non memorizzare solo definizioni; chiediti cosa spiega ogni concetto, collegalo a situazioni reali, conosci benefici, limiti e trade-off.",
  ex:"È esattamente il motivo per cui questa pagina ha Detective e Coppie: allenano il riconoscere, non il ripetere.",
  q:"Qual è la domanda che riassume l'esame?",
  a:"Sai capire e applicare la teoria organizzativa da solo?"},
 {id:"s6",part:"Cap. 1",slides:"30",title:"Cos'è un'organizzazione?",
  brief:"Prima di ogni teoria il docente chiede la tua idea: disegnala, scrivila, fai domande, costruisci una mappa.",
  hook:"Ogni teoria del Cap. 3 risponderà in modo diverso a questa stessa domanda. Torna qui alla fine del percorso.",
  ex:"Prova a scrivere una frase adesso, prima di continuare.",
  q:"Come risponderebbero tre lenti diverse?",
  a:"Classica: una macchina progettata per l'efficienza. Human Relations: una rete di persone e relazioni. Economica: un'alternativa al mercato per coordinare transazioni. Nessuna è sbagliata, ognuna vede qualcosa."},
 {id:"s7",part:"Cap. 1",slides:"32",title:"Bisogno → want → domanda",
  brief:"Un bisogno nasce da una carenza percepita. Quando diventa un desiderio specifico che puoi permetterti, è un want backed by purchasing power. Diventa domanda solo quando esprimi l'intenzione di comprare da un fornitore.",
  hook:"Sembra banale, ma è una catena precisa, ed è una trappola perfetta per una domanda a scelta multipla.",
  ex:"Un'azienda sente la carenza di dati ordinati (bisogno). Vuole una specifica soluzione cloud e ha il budget (want backed by purchasing power). Chiede un'offerta a IBM (domanda).",
  q:"Hai sete, vuoi un Rivella e hai 3 franchi in tasca. È domanda?",
  a:"Non ancora: è un want backed by purchasing power. Diventa domanda quando esprimi l'intenzione di comprarlo, per esempio al bancone."},
 {id:"s8",part:"Cap. 1",slides:"33–34",title:"La scarsità e le assunzioni che porta con sé",
  brief:"Scarsità: le risorse sono finite, quindi si può produrre solo una quantità limitata di beni. È considerata il punto di partenza dell'economia, e porta con sé assunzioni: i bisogni sono illimitati, la scarsità va superata con divisione del lavoro e scambio, si compete per beni scarsi, il mercato è la forma migliore, i migliori prevalgono.",
  hook:"Attenzione alla parola \"assunzioni\": il docente non dice che sono vere o false, ma che sono credenze con conseguenze.",
  ex:"\"Le risorse sono finite\" è vicino a un fatto. \"Il mercato è la miglior forma di organizzazione\" è un'assunzione di valore.",
  q:"Perché distinguere tra fatto e assunzione conta anche nel progetto?",
  a:"È la stessa abilità richiesta con FACT e ASSUMPTION: il voto premia chi distingue ciò che sa da ciò che crede."},
 {id:"s9",part:"Cap. 1",slides:"35–37",title:"Cosa segue da ciò che crediamo",
  brief:"Le conseguenze della scarsità ai tre livelli. Individuale: competizione, accumulo, confronto, ottimizzazione. Organizzativo: obiettivi di efficienza, specializzazione, misurazione delle performance, competizione tra unità, controllo dei costi. Economico: mercati, prezzi come meccanismo di allocazione, orientamento alla crescita.",
  hook:"La frase da portarsi a casa: le assunzioni influenzano i valori, i valori le decisioni, e le decisioni ripetute costruiscono le organizzazioni.",
  ex:"KPI, budget in competizione e controllo dei costi in una grande azienda non sono \"naturali\": sono la scarsità trasformata in struttura.",
  q:"Chi beneficia della logica della scarsità, e che problemi può creare?",
  a:"Ne beneficia chi è già forte nella competizione. Problemi possibili: disuguaglianza, consumo eccessivo di risorse, competizione interna che distrugge la collaborazione. Non esiste una sola risposta: conta il ragionamento."},
 {id:"s10",part:"Cap. 1",slides:"38–41",title:"Rovescia l'assunzione",
  brief:"Scegli un'assunzione alternativa e completa la catena: assunzione → valori → comportamento → pratiche organizzative → sistema di coordinamento. Esempio: \"il benessere non richiede consumo illimitato\" → sufficienza e sostenibilità → condividere e riparare → economia circolare, riparazioni, proprietà condivisa → mercato + cooperazione + redistribuzione.",
  hook:"Assunzioni diverse producono realtà organizzative diverse. Davanti a ogni problema, chiediti cosa stiamo assumendo su persone, bisogni, competizione, valore, successo, crescita.",
  ex:"Nel progetto funziona benissimo: quale assunzione su crescita e innovazione sta dietro le scelte di IBM?",
  q:"Completa la catena per \"la cooperazione può creare più valore della competizione\".",
  a:"Valori: fiducia, condivisione. Comportamenti: aiutarsi, scambiare conoscenza. Pratiche: obiettivi e bonus di team, partnership, comunità di pratica. Coordinamento: più reciprocità accanto al mercato."},
 {id:"s11",part:"Cap. 2",slides:"43–44",title:"L'economia è dentro la società (Polanyi)",
  brief:"L'economia è l'insieme di istituzioni e azioni che servono a soddisfare i bisogni, e dipende da cultura, valori, istruzione, tecnologia, storia, politica, diritto e risorse naturali. Per Karl Polanyi l'attività economica è embedded nella società.",
  hook:"Conseguenza per le organizzazioni: non sono sistemi chiusi. È un'idea che tornerà con la teoria dei sistemi.",
  ex:"IBM in Svizzera, in India o negli USA segue leggi del lavoro, culture e aspettative diverse, anche con la stessa strategia globale.",
  q:"Perché non basta l'organigramma per capire un'azienda?",
  a:"Perché struttura, processi e decisioni sono influenzati da norme, istituzioni, politica e cultura dell'ambiente in cui l'azienda è immersa."},
 {id:"s12",part:"Cap. 2",slides:"45–48",title:"Tre modi di far circolare le cose",
  brief:"Reciprocità: dare e ricevere per relazione e obbligo reciproco (\"ti aiuto, un giorno qualcuno aiuterà me\"). Redistribuzione: un centro raccoglie e ridistribuisce (tasse, tempio, Stato). Scambio di mercato: soldi, prezzi, contratti (\"pago per ciò che voglio\").",
  hook:"Società ⊃ economia ⊃ organizzazioni: per capire un'organizzazione devi costruire un ponte verso il suo ambiente.",
  ex:"Dentro un'azienda: il salario è mercato, il budget centrale assegnato ai reparti è redistribuzione, il collega che ti aiuta senza che tu lo chieda è reciprocità.",
  q:"Un team riceve il budget annuale dalla sede centrale. Quale forma è?",
  a:"Redistribuzione: un centro raccoglie risorse e decide come allocarle."},
 {id:"s13",part:"Cap. 2",slides:"49–51",title:"Esercizio: dove avviene davvero lo scambio?",type:"sort",
  brief:"L'esercizio fatto in classe, ora interattivo. Scegli la forma per ogni esempio.",
  hook:"La lezione della slide: le categorie non sono sempre nette, e più logiche coesistono. Le economie reali raramente usano un solo meccanismo.",
  items:[["Comprare un caffè al bar","M"],["Pagare le tasse","R"],["Un amico ti aiuta a traslocare","C"],["Ricevere l'indennità di disoccupazione","R"],["I genitori si prendono cura dei figli","C"],["Comprare una bici usata online","M"],["Un'azienda paga il salario a un dipendente","M"],["I vicini condividono gli attrezzi","C"],["L'università pubblica","R"],["Dipendenti che aiutano i colleghi senza che nessuno lo chieda","C"]]},
 {id:"s14",part:"Cap. 3",slides:"53–54",title:"Un secolo di domande sulle organizzazioni",type:"timeline",
  brief:"Ogni epoca ha posto una domanda nuova, perché il mondo delle organizzazioni era cambiato. Le teorie non si cancellano a vicenda: si sommano.",
  hook:"Il trucco per ricordarle: ogni lente è la risposta al limite di quella precedente.",
  q:"Qual è il grande cambio di domanda tra la lente classica e la contingency?",
  a:"Da \"qual è il modo migliore di organizzarsi?\" a \"non esiste un modo migliore: dipende dal contesto\"."},
 {id:"s15",part:"Cap. 3",slides:"55–58",lens:"cls",title:"Classica: la fabbrica da far funzionare",
  brief:"Con l'industrializzazione le organizzazioni crescono e il lavoro va diviso, standardizzato e coordinato su larga scala. Design tipico: gerarchia chiara, divisione del lavoro, ruoli e regole formali, processi standard; il management pianifica e controlla, i dipendenti eseguono.",
  hook:"Divide → Specialize → Standardize → Control → Optimize. La struttura permette di crescere, ma troppo controllo rende rigidi.",
  ex:"Dal video su Toyota: lavoro standardizzato e misura dei tempi sono ancora logica classica. Ma gli operai possono fermare la linea e migliorare il processo: pensano, non solo eseguono.",
  q:"Cosa resta oggi della lente classica?",
  a:"Job description, organigrammi, SOP e processi standard, KPI, responsabilità gerarchica."},
 {id:"s16",part:"Cap. 3",slides:"59–62",lens:"hr",title:"Human Relations: ci sono persone dentro la macchina",
  brief:"La teoria classica trattava i dipendenti come parti del sistema produttivo. Mayo, Maslow, Herzberg e McGregor si chiedono cosa succede se si considera il lato umano e sociale.",
  hook:"Le persone sono motivate da più del denaro, i gruppi informali influenzano la performance, e le assunzioni del management plasmano il design dell'organizzazione.",
  ex:"Oggi: engagement, team development, leadership development, psychological safety, employee experience, cultura.",
  q:"Cosa aggiunge questa lente rispetto alla classica, in una frase?",
  a:"Le organizzazioni non sono solo strutture e processi, ma anche reti di persone e relazioni."},
 {id:"s17",part:"Cap. 3",slides:"63–65",lens:"dec",title:"Decisionale: nessuno sa tutto",
  brief:"Le teorie precedenti assumevano che i manager potessero trovare la soluzione migliore. Simon lo contesta: informazioni incomplete, alternative limitate, tempo e capacità cognitive limitate. Si sceglie una soluzione abbastanza buona (satisficing), e le organizzazioni creano regole e routine per aiutare le decisioni.",
  hook:"Il design organizzativo è anche design delle decisioni: chi riceve quali informazioni, e chi può decidere cosa?",
  ex:"Razionalità perfetta: tutte le informazioni e tutte le alternative → decisione ottimale. Razionalità limitata: informazioni incomplete → decisione soddisfacente.",
  q:"Cosa significa satisficing?",
  a:"Scegliere la prima opzione che supera una soglia accettabile, invece di cercare all'infinito quella ottimale."},
 {id:"s18",part:"Cap. 3",slides:"66–67",lens:"sys",title:"Sistemi: tutto è collegato",
  brief:"Uno dei cambi concettuali più grandi. Prima si guardava soprattutto dentro l'organizzazione; ora la domanda è come interagisce con il suo ambiente. Prospettiva sociotecnica: tecnologia, persone, struttura e processi vanno ottimizzati insieme.",
  hook:"Nuova tecnologia → cambiano i processi → cambiano i lavori → cambiano le competenze → cambia la collaborazione → cambia la struttura.",
  ex:"Introdurre l'AI generativa in un'azienda come IBM non è un progetto IT: è un cambiamento di ruoli, competenze e coordinamento.",
  q:"Cosa resta oggi della lente dei sistemi?",
  a:"Digital transformation, ecosistemi organizzativi, systems thinking, processi end-to-end, interdipendenze."},
 {id:"s19",part:"Cap. 3",slides:"68–69",lens:"con",title:"Contingency: dipende",
  brief:"La classica cercava il modo migliore di organizzarsi; la contingency risponde che non esiste. Il design adatto dipende da strategia, ambiente, tecnologia, dimensione, incertezza, persone e capacità.",
  hook:"Un buon design organizzativo non copia le best practice: crea fit.",
  ex:"Ambiente stabile: gerarchia, specializzazione e standard possono funzionare. Ambiente dinamico: decentramento, team e sperimentazione funzionano meglio.",
  q:"Cita due dibattiti di oggi che sono pura contingency.",
  a:"Agile vs gerarchico, centralizzato vs decentrato, strutture funzionali vs per prodotto, remoto vs ufficio, startup vs corporate."},
 {id:"s20",part:"Cap. 3",slides:"70–71",lens:"eco",title:"Economica: perché non tutto è mercato?",
  brief:"Transaction Cost Economics: a volte comprare sul mercato è efficiente, a volte conviene portare l'attività dentro l'organizzazione, a seconda dei costi di coordinamento. Agency Theory: attori diversi hanno interessi diversi (azionisti e management), quindi servono incentivi, monitoraggio, governance e contratti.",
  hook:"I confini dell'organizzazione e la governance esistono in parte per gestire transazioni, incentivi e interessi in conflitto.",
  ex:"Oggi: outsourcing, partnership strategiche, corporate governance, sistemi di incentivi, piattaforme, decisioni make-or-buy.",
  q:"Qual è la domanda di fondo di questa lente?",
  a:"Perché esistono le organizzazioni, invece di coordinare tutto tramite il mercato?"},
 {id:"s21",part:"Cap. 3",slides:"72–73",lens:"ins",title:"Istituzionale: essere legittimi",
  brief:"L'efficienza non spiega ogni decisione. A volte si adottano pratiche perché sono considerate legittime, professionali, attese, socialmente accettabili. Le pressioni sono tre: regolazione, norme professionali, imitazione (isomorfismo istituzionale).",
  hook:"Le organizzazioni non cercano solo efficienza, cercano anche legittimità.",
  ex:"Perché tutti adottano report di sostenibilità, politiche di diversity, metodi agili, strategie AI, uffici di compliance?",
  q:"Perché le organizzazioni dello stesso settore diventano sempre più simili?",
  a:"Per pressioni regolatorie (leggi), normative (professioni ed esperti) e mimetiche (copiare chi sembra avere successo)."},
 {id:"s22",part:"Cap. 3",slides:"76–81",title:"Theory Detective: Alpine Manufacturing",type:"detective",
  brief:"Azienda industriale svizzera con 800 dipendenti. Negli ultimi due anni:",
  facts:["la produttività è calata","il turnover è aumentato","le decisioni richiedono troppo tempo","i reparti lavorano sempre più a silos","i clienti vogliono personalizzazione più rapida","i concorrenti introducono nuove tecnologie digitali","il management ha risposto con più regole e reporting"],
  hook:"È il formato dell'esame, e del progetto. Scegli una lente: quale problema vede, cosa raccomanda, cosa si perde?",
  q:"Dopo aver provato tutte le lenti: perché la risposta del management (più regole) è probabilmente sbagliata?",
  a:"È una risposta puramente classica a un problema che diverse lenti leggono come mancanza di fit (contingency), motivazione (HR), colli di bottiglia decisionali (decisionale) e disallineamento tecnologico (sistemi). Più controllo rischia di peggiorare silos, lentezza e turnover."},
 {id:"s23",part:"Chiusura",slides:"82–83",title:"Un'organizzazione moderna è tutto questo insieme",
  brief:"L'eredità dell'era industriale (gerarchia, pianificazione centralizzata, divisione funzionale, standardizzazione, budget e controllo) ha funzionato per efficienza, prevedibilità e scalabilità. Fatica con incertezza, cambiamento rapido, innovazione e lavoro cross-funzionale.",
  hook:"Non esiste una sola diagnosi corretta: ogni teoria fa una domanda diversa.",
  ex:"Un'organizzazione moderna è contemporaneamente una macchina, un sistema sociale, un sistema decisionale, un sistema aperto, un sistema contingente, un sistema economico e un attore istituzionale.",
  q:"Collega ogni metafora alla sua lente e al bisogno che esprime.",
  a:"Macchina → classica: i processi devono essere efficienti. Sistema sociale → HR: le persone devono collaborare. Sistema decisionale → decisionale: le informazioni devono diventare decisioni. Sistema aperto → sistemi: dipende dall'ambiente. Sistema contingente → contingency: la struttura deve adattarsi al contesto. Sistema economico → economica: incentivi e transazioni contano. Attore istituzionale → istituzionale: legittimità e aspettative della società contano."},
 {id:"s24",part:"Chiusura",slides:"85–86",title:"Come saranno le prossime lezioni",
  brief:"Ogni lezione: benvenuto e recap; ogni gruppo presenta i progressi in 5 minuti (lavoro fatto, key learnings, aiuto necessario); feedback e apprendimento di gruppo; lezione con esercizi e riflessione; input facoltativi o studio autonomo.",
  hook:"To do per il 30.09: iniziare a studiare per l'esame, iniziare la desk research, conoscere l'azienda, raccogliere le prime osservazioni.",
  ex:"Per il Gruppo 2: arrivare con prime osservazioni su scopo, stakeholder, struttura e processi di IBM, già etichettate come FACT o ASSUMPTION.",
  q:"Cosa porta il tuo gruppo nei 5 minuti di aggiornamento?",
  a:"Lavoro fatto, key learnings, aiuto necessario."}
];
